select string_agg(w, '|' order by w collate "und-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "en-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "de-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "sv-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "da-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "fr-CA-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "tr-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "es-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "cs-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "hu-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "lt-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "ja-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "zh-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "ko-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "th-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "ru-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "el-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "ar-x-icu") from gxo_w;
select string_agg(w, '|' order by w collate "unicode") from gxo_w;
select string_agg(w, '|' order by w collate "C") from gxo_w;
select string_agg(w, '|' order by w collate "ucs_basic") from gxo_w;
select string_agg(w, '|' order by w collate "pg_c_utf8") from gxo_w;
select string_agg(w, '|' order by w collate "pg_unicode_fast") from gxo_w;
select string_agg(w, '|' order by w collate "en-x-icu" desc) from gxo_w;
create collation gxo_kn (provider = icu, locale = 'und-u-kn');
select string_agg(w, '|' order by w collate gxo_kn) from gxo_w;
create collation gxo_kf (provider = icu, locale = 'und-u-kf-upper');
select string_agg(w, '|' order by w collate gxo_kf) from gxo_w;
create collation gxo_kfl (provider = icu, locale = 'en-u-kf-lower');
select string_agg(w, '|' order by w collate gxo_kfl) from gxo_w;
create collation gxo_ka (provider = icu, locale = 'und-u-ka-shifted');
select string_agg(w, '|' order by w collate gxo_ka) from gxo_w;
create collation gxo_s1 (provider = icu, locale = 'und-u-ks-level1');
select string_agg(w, '|' order by w collate gxo_s1) from gxo_w;
create collation gxo_s2 (provider = icu, locale = 'und-u-ks-level2');
select string_agg(w, '|' order by w collate gxo_s2) from gxo_w;
create collation gxo_kc (provider = icu, locale = 'en-u-kc-ks-level1');
select string_agg(w, '|' order by w collate gxo_kc) from gxo_w;
create collation gxo_s4 (provider = icu, locale = 'und-u-ka-shifted-ks-level4');
select string_agg(w, '|' order by w collate gxo_s4) from gxo_w;
create collation gxo_id (provider = icu, locale = 'und-u-ks-identic');
select string_agg(w, '|' order by w collate gxo_id) from gxo_w;
create collation gxo_pb (provider = icu, locale = 'de-u-co-phonebk');
select string_agg(w, '|' order by w collate gxo_pb) from gxo_w;
create collation gxo_trad (provider = icu, locale = 'es-u-co-trad');
select string_agg(w, '|' order by w collate gxo_trad) from gxo_w;
create collation gxo_kv (provider = icu, locale = 'und-u-ka-shifted-kv-symbol');
select string_agg(w, '|' order by w collate gxo_kv) from gxo_w;
create collation gxo_legacy (provider = icu, locale = '@colStrength=secondary;colNumeric=yes');
select string_agg(w, '|' order by w collate gxo_legacy) from gxo_w;
create collation gxo_nd1 (provider = icu, locale = 'und-u-ks-level1', deterministic = false);
create collation gxo_nd2 (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
select count(distinct w collate gxo_nd1), count(distinct w collate gxo_nd2), count(distinct w) from gxo_w;
select count(*) from (select w collate gxo_nd2 from gxo_w group by 1) s;
select a.w, b.w from gxo_w a join gxo_w b on a.w = b.w collate gxo_nd1 and a.w < b.w collate "C" order by 1 collate "C", 2 collate "C";
select min(w collate "de-x-icu"), max(w collate "de-x-icu"), min(w collate "sv-x-icu"), max(w collate "sv-x-icu") from gxo_w;
select w, w < 'm' collate "en-x-icu" as lt_en, w < 'm' collate "C" as lt_c, greatest(w, 'm' collate "tr-x-icu") from gxo_w where length(w) = 1 order by w collate "C";
drop collation gxo_kn;
drop collation gxo_kf;
drop collation gxo_kfl;
drop collation gxo_ka;
drop collation gxo_s1;
drop collation gxo_s2;
drop collation gxo_kc;
drop collation gxo_s4;
drop collation gxo_id;
drop collation gxo_pb;
drop collation gxo_trad;
drop collation gxo_kv;
drop collation gxo_legacy;
drop collation gxo_nd1, gxo_nd2;
drop table gxo_w;
